import React from 'react';
import { Link } from 'react-router-dom';

function MovieCard({ movie }) {
  return (
    // Link가 카드 전체를 감싸도록 변경
    <Link to={`/movie/${movie.id}`} style={styles.link}>
      <div style={styles.card}>
        {/* 영화 포스터 이미지 */}
        <img src={movie.poster_path} alt={movie.title} style={styles.poster} />
        
        {/* 영화 정보 텍스트 영역 */}
        <div style={styles.info}>
          <h3 style={styles.title}>{movie.title}</h3>
          
          {/* movie 객체에 details가 있으면 상세 정보를, 없으면 description을 표시 */}
          {movie.details ? (
            <div style={styles.details}>
              {/* Object.entries를 사용해 key-value 쌍을 순회하며 렌더링 */}
              {Object.entries(movie.details).map(([key, value]) => (
                <p key={key} style={styles.detailItem}>
                  <span style={styles.detailKey}>{key}:</span> {value}
                </p>
              ))}
            </div>
          ) : (
            <p style={styles.description}>{movie.description}</p>
          )}
        </div>
      </div>
    </Link>
  );
}

const styles = {
  link: {
    textDecoration: 'none', // 링크의 밑줄 제거
    color: 'inherit', // 부모 요소의 글자색 상속
  },
  card: {
    display: 'flex', // 이미지와 정보를 가로로 배치
    backgroundColor: '#ffffff',
    borderRadius: '12px',
    padding: '1rem',
    boxShadow: '0 4px 12px rgba(0, 0, 0, 0.08)', // 은은한 그림자 효과
    transition: 'transform 0.2s ease-in-out', // 호버 효과를 위한 transition
    height: '100%', // 그리드 셀 높이에 맞춤
    overflow: 'hidden',
  },
  poster: {
    width: '120px',
    height: '170px',
    objectFit: 'cover', // 이미지 비율을 유지하면서 채우기
    borderRadius: '8px',
    backgroundColor: '#e0e0e0', // 이미지가 없을 때 배경색
  },
  info: {
    flex: 1, // 남은 공간을 모두 차지
    paddingLeft: '1.5rem',
    display: 'flex',
    flexDirection: 'column',
  },
  title: {
    margin: '0 0 0.8rem 0',
    fontSize: '1.2rem',
    fontWeight: 'bold',
  },
  description: {
    margin: 0,
    fontSize: '0.9rem',
    color: '#555',
    lineHeight: '1.5',
  },
  details: {
    fontSize: '0.85rem',
    color: '#333',
    lineHeight: '1.6',
  },
  detailItem: {
    margin: '0 0 4px 0',
  },
  detailKey: {
    fontWeight: '600',
    marginRight: '4px',
    color: '#000',
  }
};

export default MovieCard;
